using C64Lib;

// The deck's pictures: generated by art/presentation_art.py into art/build/
// (embedded by C64Presentation.csproj). art/ART.md is the catalogue: size,
// mode, bytes and where/how to draw each one. Draw with
//     C64.Screen.DrawImage(column, row, C64Address.FromLabel("img_<Label>"));
// Bytes = what the image adds to the program (the compressed payload).

// --- The storyboard's asset list (round 5): about 6.3 KB ------------------

// The title picture (opens the deck, slide 1; 40x25 hires, 1718 bytes) is a
// file on the deck's disk too: Master.Cover loads it into buf_Picture.

// The three Catacombs shots (9,073 bytes) are files on the deck's disk
// (disk.txt), not part of the program: ArtDisk.Load(DiskPicture.X) loads one
// into a single shared buffer and returns its address for DrawImage. The
// buffer is sized by 64tass for the largest file that build can load
// (art/presentation_art.py writes both buffer files): the deck loads only
// the room and the cover, the art and gallery scenes the shots as well.
//   A1 ShotRoom   40x21 mc  3755  DrawImage(0, 0, ..), split at 21 (art scenes, gallery)
//   A2 ShotTitle  36x18 mc  2748  DrawImage(2, 3, ..), full screen (art scenes)
//   A3 ShotBoss   40x15 mc  2570  DrawImage(0, 0, ..), split at 15 (art scenes, gallery)
#if SCENE_ART || SCENE_DISK || SCENE_ENGINE
[assembly: RawAssembly(Resource = "picture_buffer_all.asm")]               // buf_Picture  3755
#else
[assembly: RawAssembly(Resource = "picture_buffer.asm")]                   // buf_Picture  3695 (the room)
#endif
// A5 the C64 breadbox, hi-res (slide 3)
[assembly: RawImage(Resource = "breadbox.img", Label = "Breadbox")]        // 18x8 hires   377
// A6 icons, PIXELS ONLY: set the cells' colours first. Only the art review
// pages show them since slide 9 lost its topic row (with the Borrow slide);
// icon_int8/stack/bitmap/object are built but undeclared since the cuts.
#if SCENE_ART
[assembly: RawImage(Resource = "icon_gc.img", Label = "IconGc")]           // 3x3 hires     74
[assembly: RawImage(Resource = "icon_string.img", Label = "IconString")]   // 3x3 hires     47
#endif
// The section icon of slide 9 (from the extras)
[assembly: RawImage(Resource = "sec_chip.img", Label = "SecChip")]         //  6x6 hires   204

// The section icon of slide 11, Small and fast (an extra, see below).
[assembly: RawImage(Resource = "sec_chart.img", Label = "SecChart")]       //  6x6 hires   129

